package com.abhishek.hotelbooking.entity;
import com.abhishek.hotelbooking.enums.*; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.LocalDate;
@Entity @Table(name="bookings",indexes={@Index(name="idx_booking_room_dates",columnList="room_id,check_in,check_out")}) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Booking { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) private User user; @ManyToOne(fetch=FetchType.LAZY,optional=false) private Room room; @Column(name="check_in",nullable=false) private LocalDate checkIn; @Column(name="check_out",nullable=false) private LocalDate checkOut; @Column(nullable=false,precision=12,scale=2) private BigDecimal totalAmount; @Enumerated(EnumType.STRING) @Column(nullable=false) private BookingStatus status=BookingStatus.CONFIRMED; @Enumerated(EnumType.STRING) @Column(nullable=false) private PaymentStatus paymentStatus=PaymentStatus.PENDING; }